import java.util.Scanner;
public class ArrayAverage { public static void main(String[] x){Scanner s=new Scanner(System.in);System.out.print("Enter array size (1-100): ");if(!s.hasNextInt()){System.out.println("Enter a size from 1 to 100.");return;}int n=s.nextInt();if(n<1||n>100){System.out.println("Array size must be from 1 to 100.");return;}long sum=0;for(int i=0;i<n;i++){if(!s.hasNextInt()){System.out.println("Enter exactly "+n+" whole numbers.");return;}sum+=s.nextInt();}if(s.hasNext()){System.out.println("Enter only the array values.");return;}System.out.printf("Average: %.2f%n",(double)sum/n);}}
